import { useEffect, useState } from "react";
import axios from "axios";

function Dashboard() {

  const [queues, setQueues] = useState([]);

  const [form, setForm] = useState({
    patientName: "",
    doctor: "",
    department: "",
    date: ""
  });

  // GET QUEUE LIST
  const fetchQueues = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/queue/all");
      setQueues(res.data);
    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    fetchQueues();

    const interval = setInterval(() => {
      fetchQueues();
    }, 5000); // live refresh

    return () => clearInterval(interval);
  }, []);

  // BOOK OP
  const bookOP = async () => {
    try {
      await axios.post("http://localhost:5000/api/queue/add", form);

      alert("OP Booked Successfully");

      setForm({
        patientName: "",
        doctor: "",
        department: "",
        date: ""
      });

      fetchQueues();

    } catch (err) {
      alert("Booking Failed");
    }
  };

  // CONFIRM OP
  const confirmOP = async (id) => {
    await axios.put(`http://localhost:5000/api/queue/confirm/${id}`);
    fetchQueues();
  };

  // JOIN QUEUE
  const joinQueue = async (id) => {
    try {
      await axios.put(`http://localhost:5000/api/queue/join/${id}`);
      alert("Joined Queue");
      fetchQueues();
    } catch (err) {
      alert(err.response.data);
    }
  };

  // COMPLETE OP
  const completeOP = async (id) => {
    await axios.delete(`http://localhost:5000/api/queue/complete/${id}`);
    fetchQueues();
  };

  return (
    <div style={{ padding: "30px" }}>

      <h1>🏥 Hospital OP Queue System</h1>

      {/* BOOK OP FORM */}
      <div style={{ marginBottom: "20px" }}>
        <input
          placeholder="Patient Name"
          value={form.patientName}
          onChange={(e) => setForm({ ...form, patientName: e.target.value })}
        />

        <input
          placeholder="Doctor"
          value={form.doctor}
          onChange={(e) => setForm({ ...form, doctor: e.target.value })}
        />

        <input
          placeholder="Department"
          value={form.department}
          onChange={(e) => setForm({ ...form, department: e.target.value })}
        />

        <input
          type="date"
          value={form.date}
          onChange={(e) => setForm({ ...form, date: e.target.value })}
        />

        <button onClick={bookOP}>Book OP</button>
      </div>

      {/* QUEUE LIST */}
      {queues.length === 0 ? (
        <p>No Queue Data</p>
      ) : (
        queues.map((q) => (
          <div
            key={q._id}
            style={{
              border: "1px solid black",
              padding: "10px",
              marginBottom: "10px",
              background:
                q.status === "Waiting"
                  ? "#fff3cd"
                  : q.status === "Confirmed"
                  ? "#cce5ff"
                  : q.status === "InQueue"
                  ? "#d4edda"
                  : "#f8d7da"
            }}
          >

            <h3>Token: {q.tokenNumber}</h3>
            <p>Patient: {q.patientName}</p>

            <p>
              Status: <b>{q.status}</b>
            </p>

            {/* BUTTONS */}
            <button onClick={() => confirmOP(q._id)}>
              Confirm
            </button>

            <button onClick={() => joinQueue(q._id)}>
              Join Queue
            </button>

            <button onClick={() => completeOP(q._id)}>
              Complete
            </button>

          </div>
        ))
      )}

    </div>
  );
}

export default Dashboard;
